pub fn add_tax(amount: i64) -> i64 {
    return amount + amount / 10;
}

pub fn longest(words: &[String]) -> i64 {
    let mut best: i64 = 0;
    for word in words.to_vec() {
        if word.len() as i64 > best {
            best = word.len() as i64;
        }
    }
    return best;
}

